-- Fixtures for parity/ai-assistant.jsonl. Idempotent: run before every
-- parity pass against the scratch database (never production):
--
--   psql postgres://pg:pg@127.0.0.1:55499/norviq -f parity/ai-assistant-setup.sql
--
-- Users a2a2a2a2-0000-4000-8000-00000000000N: 1 free (fixtures), 2 pro
-- (memos), 3 free (message quota), 4 free with no rows at all.
-- Encrypted columns are sealed with the non-production fallback PII key both
-- servers use in development. Mutating cases run twice (Vapor, then v2), so
-- triggers keep the fixtures repeatable: the fixture conversation and memo
-- cannot be deleted, and the fixture action cannot leave `pending`.

BEGIN;

-- The keep-fixture triggers below would block this cleanup on a rerun.
DROP TRIGGER IF EXISTS parity_ai_keep_conversation ON ai_conversations;
DROP TRIGGER IF EXISTS parity_ai_keep_memo ON position_memos;
DROP TRIGGER IF EXISTS parity_ai_keep_pending ON ai_pending_actions;
DROP TRIGGER IF EXISTS parity_ai_reset_audit ON ai_action_audits;

DELETE FROM ai_usage_monthly WHERE user_id::text LIKE 'a2a2a2a2-0000-4000-8000-%';
DELETE FROM users WHERE id::text LIKE 'a2a2a2a2-0000-4000-8000-%';

