  ('a2a2a2a2-0000-4000-8000-000000000003', 'parity-ai-quota@example.com', 'x', now(), true),
  ('a2a2a2a2-0000-4000-8000-000000000004', 'parity-ai-empty@example.com', 'x', now(), true);

